import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    q = int(data[1])
    label = list(range(n + 1))
    out = []
    idx = 2
    for _ in range(q):
        if data[idx] == '1':
            a = int(data[idx + 1])
            b = int(data[idx + 2])
            idx += 3
            la = label[a]
            lb = label[b]
            if la != lb:
                for v in range(1, n + 1):
                    if label[v] == lb:
                        label[v] = la
        else:
            a = int(data[idx + 1])
            idx += 2
            la = label[a]
            cnt = 0
            for v in range(1, n + 1):
                if label[v] == la:
                    cnt += 1
            out.append(str(cnt))
    print('\n'.join(out))


main()
